@page "/shipments"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Shipments Dashboard</PageTitle>

<h1>Shipments Dashboard</h1>

<div class="mb-3">
    <button class="btn btn-success" @onclick="ShowCreateForm">+ New Shipment</button>
</div>

@if (showCreateForm)
{
    <div class="card mb-4">
        <div class="card-body">
            <h5>Create New Shipment</h5>
            <EditForm Model="newShipment" OnValidSubmit="CreateShipment" FormName="CreateShipment">
                <DataAnnotationsValidator />
                <div class="row">
                    <div class="col-md-4 mb-2">
                        <label class="form-label">Origin</label>
                        <InputText @bind-Value="newShipment.Origin" class="form-control" />
                    </div>
                    <div class="col-md-4 mb-2">
                        <label class="form-label">Destination</label>
                        <InputText @bind-Value="newShipment.Destination" class="form-control" />
                    </div>
                    <div class="col-md-4 mb-2">
                        <label class="form-label">Customer Email</label>
                        <InputText @bind-Value="newShipment.CustomerEmail" class="form-control" />
                    </div>
                </div>
                <div class="row">
                    <div class="col-md-6 mb-2">
                        <label class="form-label">Description</label>
                        <InputText @bind-Value="newShipment.Description" class="form-control" />
                    </div>
                    <div class="col-md-3 mb-2">
                        <label class="form-label">Estimated Delivery</label>
                        <InputDate @bind-Value="newShipment.EstimatedDelivery" class="form-control" />
                    </div>
                </div>
                <button type="submit" class="btn btn-primary me-2">Create</button>
                <button type="button" class="btn btn-outline-secondary" @onclick="CancelCreate">Cancel</button>
            </EditForm>
        </div>
    </div>
}

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else if (shipments.Count == 0)
{
    <p>No shipments found.</p>
}
else
{
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Filter by destination..."
               @bind="filterText" @bind:event="oninput" />
    </div>

    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Shipped</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var s in FilteredShipments)
            {
                <tr>
                    <td><code>@s.TrackingNumber</code></td>
                    <td>@s.Origin</td>
                    <td>@s.Destination</td>
                    <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                    <td>@s.ShippedDate.ToString("yyyy-MM-dd")</td>
                    <td>@s.EstimatedDelivery.ToString("yyyy-MM-dd")</td>
                    <td>
                        <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                value="@s.Status" @onchange="(e) => UpdateStatus(s, e)">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<Shipment>? shipments;
    private Shipment newShipment = new();
    private bool showCreateForm;
    private string filterText = string.Empty;

    private IEnumerable<Shipment> FilteredShipments =>
        shipments?.Where(s => string.IsNullOrEmpty(filterText)
            || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)) ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private void ShowCreateForm() => showCreateForm = true;
    private void CancelCreate() => showCreateForm = false;

    private async Task CreateShipment()
    {
        newShipment.TrackingNumber = $"TRK-{Guid.NewGuid().ToString()[..8].ToUpper()}";
        newShipment.ShippedDate = DateTime.UtcNow;
        if (newShipment.EstimatedDelivery == default)
            newShipment.EstimatedDelivery = DateTime.UtcNow.AddDays(5);
        newShipment.Status = ShipmentStatus.Pending;

        var created = await ShipmentService.CreateShipmentAsync(newShipment);
        shipments?.Insert(0, created);
        newShipment = new();
        showCreateForm = false;
    }

    private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.InTransit => "bg-info",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };
}

